WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_eng_s_rest'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '间隔休息型', 'kp-eng-s-rest', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "间隔休息型"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "把“休息”当作效率为 0 的工作时间，依然采用周期捆绑法。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "特征描述：“甲工作 3 天休息 1 天，乙工作 5 天休息 2 天”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心破题"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这实际上是复杂版的周期轮换。甲的周期是 4 天（干3休1），乙的周期是 7 天（干5休2）。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[赋总量, 出每个人每天的正常效率] --> B[找出所有参与人的周期的最小公倍数, 作为一个大循环周期]\nB --> C[计算在这个大循环周期内, 甲干了几天, 乙干了几天, 算出大周期总产量]\nC --> D[用 W总 ÷ 大周期产量 = N个大周期 ... 余数]\nD --> E[对着余数, 在草稿纸上画出第一天、第二天每个人在干嘛, 逐步扣减]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 挖沟，甲单独需 12 天，乙单独需 15 天。现甲挖 2天休 1天，乙挖 3天休 1天。两人合作需要几天？选项：A. 8  B. 9  C. 10  D. 11"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "基础数据：W=60，P甲=5，P乙=4。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "找大周期：甲的周期是 3 天，乙的周期是 4 天。3和4的公倍数是 12 天。大周期定为 12 天。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算大周期产量：12天里，甲休了 4 天干了 8 天；乙休了 3 天干了 9 天。大周期总产 = 8×5 + 9×4 = 40 + 36 = 76。由于 76 > 60，说明根本用不了一个大周期！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "逐步枚举（既然一周期都不到，直接拆天算）："}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "  - 第 1,2 天：甲乙都干。完成 (5+4)×2 = 18。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "  - 第 3 天：甲休，乙干。完成 4。累计 22。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "  - 第 4 天：甲干，乙休。完成 5。累计 27。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "  - ... 按照表格画正字，直到累计满 60。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "盲目求大周期：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "像上题，大周期长达 12 天，产出远大于总量。如果一上来就死磕公式会很僵化。当周期不统一且总量不大时，“画表格枚举每天的产量”反而是考场上最快、最不易算错的土办法！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "练就“画表格”绝技。横轴写第1天到第10天，纵轴写甲乙。打钩代表干，打叉代表休。一目了然。"}]}]}$$ AS jsonb), NULL, '间隔休息型的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "间隔休息型"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_s_rest", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
